import{_ as t,o as s,c as n,a4 as i}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0031 — Limitation de débit : compteurs en base, seuils de l'exploitant","description":"Extrait de docs/adr/0031-limitation-de-debit.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0031 — Limitation de débit : compteurs en base, seuils de l'exploitant","description":"Extrait de docs/adr/0031-limitation-de-debit.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0031-limitation-de-debit.md","filePath":"developpeurs/adr/0031-limitation-de-debit.md"}`),r={name:"developpeurs/adr/0031-limitation-de-debit.md"};function a(o,e,l,u,d,c){return s(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0031--limitation-de-débit--compteurs-en-base-seuils-de-lexploitant" tabindex="-1">ADR-0031 — Limitation de débit : compteurs en base, seuils de l&#39;exploitant <a class="header-anchor" href="#adr-0031--limitation-de-débit--compteurs-en-base-seuils-de-lexploitant" aria-label="Permalink to &quot;ADR-0031 — Limitation de débit : compteurs en base, seuils de l&#39;exploitant {#adr-0031--limitation-de-débit--compteurs-en-base-seuils-de-lexploitant}&quot;">​</a></h1><p><strong>Date :</strong> 17 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit de sécurité du 15 septembre 2026 (dernier constat de gravité élevée) ; CDC_CMS_AI_Native_v1.1 §8.1, §8.3 et §14.8 ; complète l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0015-captcha-non-configure-refus-de-soumission">ADR-0015</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0026-installation-guidee-cle-d-installation">ADR-0026</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0029-sorties-reseau-du-socle-ia">ADR-0029</a> ; suit le retrait de Redis (ménage du 16 septembre)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Aucune route du Core ne limitait le nombre de requêtes d&#39;un même client. Les protections existantes visaient autre chose :</p><ul><li><strong>Le verrouillage de compte</strong> protège un compte. Il ne protège ni l&#39;instance, qui calcule un hachage de mot de passe et écrit une ligne de journal par essai, ni les comptes d&#39;autrui, qu&#39;un tiers peut verrouiller exprès. Il n&#39;arrête pas non plus la pulvérisation : quelques essais sur beaucoup de logins.</li><li><strong>Le captcha</strong> se vérifie à l&#39;acte qui engage (ADR-0015). Une fois résolu, rien ne borne ce qui suit. Pour l&#39;assistant public, un défi résolu ouvre quinze tours, <strong>chacun facturé</strong>. Des ouvertures en chaîne mènent au plafond de budget, qui coupe alors l&#39;assistant pour tous les visiteurs.</li><li><strong>Aucune protection</strong> sur l&#39;inscription d&#39;un usager, qui envoie un courriel de confirmation à l&#39;adresse saisie, ni sur les essais de clé d&#39;installation, les essais de jeton de suivi, la recherche et l&#39;émission de défis anti-robot.</li></ul><p>Une limite de débit se tient forcément quelque part hors de la requête. Redis venait d&#39;être retiré de la pile parce qu&#39;aucune ligne de code ne l&#39;appelait.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Le Core limite lui-même le débit de ses routes anonymes. Les compteurs sont dans PostgreSQL, les seuils sont fixés par l&#39;exploitant, et des valeurs par défaut sont actives dès l&#39;installation.</strong></p><h3 id="1-des-compteurs-en-base-par-fenêtre-fixe" tabindex="-1">1. Des compteurs en base, par fenêtre fixe <a class="header-anchor" href="#1-des-compteurs-en-base-par-fenêtre-fixe" aria-label="Permalink to &quot;1. Des compteurs en base, par fenêtre fixe {#1-des-compteurs-en-base-par-fenêtre-fixe}&quot;">​</a></h3><p>La table <code>rate_limit_counters</code> porte une ligne par couple (politique et empreinte, début de fenêtre).</p><ul><li><strong>Un seul aller-retour par requête :</strong> un <code>INSERT … ON CONFLICT … DO UPDATE SET hits = hits + 1 RETURNING hits</code>.</li><li><strong>Au-delà du seuil :</strong> la réponse est <strong>429</strong>, avec <code>Retry-After</code>.</li><li><strong>Le compteur est écrit dans une transaction à part, validée tout de suite.</strong> Un mot de passe faux doit compter, même si la route échoue ensuite.</li><li><strong>Les fenêtres sont alignées sur l&#39;époque Unix.</strong> Plusieurs workers ou plusieurs instances comptent ainsi sur la même ligne sans se concerter.</li><li><strong>Une tâche horaire de l&#39;ordonnanceur (<code>rate_limit_purge</code>) supprime les fenêtres terminées.</strong></li></ul><p>La fenêtre fixe laisse passer une rafale à la frontière de deux fenêtres, au plus deux fois le seuil. C&#39;est accepté : ces seuils bornent un abus, ils ne mesurent pas un débit.</p><h3 id="2-deux-dimensions" tabindex="-1">2. Deux dimensions <a class="header-anchor" href="#2-deux-dimensions" aria-label="Permalink to &quot;2. Deux dimensions {#2-deux-dimensions}&quot;">​</a></h3><p>Chaque route sensible compte sur deux dimensions :</p><ul><li><strong>Par adresse du client :</strong> cela arrête un client qui essaie beaucoup de cibles.</li><li><strong>Par cible :</strong> organisation et login (agent ou usager, comptés séparément), courriel, numéro de téléphone ou référence de dossier. Cela arrête la pulvérisation depuis beaucoup d&#39;adresses.</li></ul><p>Sur la connexion, le verrouillage de compte reste en place, et les deux mécanismes se complètent. Avec les réglages par défaut, le dixième échec verrouille le compte et le onzième essai est refusé avant toute lecture du compte.</p><h3 id="3-aucune-donnée-en-clair" tabindex="-1">3. Aucune donnée en clair <a class="header-anchor" href="#3-aucune-donnée-en-clair" aria-label="Permalink to &quot;3. Aucune donnée en clair {#3-aucune-donnée-en-clair}&quot;">​</a></h3><p>L&#39;identité comptée est remplacée par son empreinte SHA-256, en base comme au journal, qui n&#39;en garde que douze caractères. <strong>C&#39;est une pseudonymisation, pas une anonymisation</strong> : l&#39;espace des adresses IPv4 se parcourt. On l&#39;assume parce qu&#39;une ligne ne vit pas plus longtemps que sa fenêtre, entre quelques minutes et un jour.</p><h3 id="4-les-seuils-appartiennent-à-lexploitant" tabindex="-1">4. Les seuils appartiennent à l&#39;exploitant <a class="header-anchor" href="#4-les-seuils-appartiennent-à-lexploitant" aria-label="Permalink to &quot;4. Les seuils appartiennent à l&#39;exploitant {#4-les-seuils-appartiennent-à-lexploitant}&quot;">​</a></h3><p>L&#39;abus vise l&#39;instance, et c&#39;est l&#39;exploitant qui la protège. Chaque limite est réglée par une variable d&#39;environnement <code>RATE_LIMIT_&lt;POLITIQUE&gt;_PER_IP</code> ou <code>…_PER_TARGET</code>, au format <code>N/durée</code>.</p><ul><li><strong>Une variable absente garde la valeur par défaut</strong>, jamais « pas de limite ».</li><li><strong><code>off</code> désactive une limite explicitement.</strong></li><li><strong>Une valeur invalide ou vide empêche l&#39;API et l&#39;ordonnanceur de démarrer.</strong> Un seuil mal écrit ne doit pas devenir en silence une absence de limite.</li></ul><p>Une organisation ne peut pas les modifier : sur une instance partagée, elle pourrait lever la protection de toutes les autres.</p><h3 id="5-une-adresse-fiable-ou-aucune-confiance" tabindex="-1">5. Une adresse fiable, ou aucune confiance <a class="header-anchor" href="#5-une-adresse-fiable-ou-aucune-confiance" aria-label="Permalink to &quot;5. Une adresse fiable, ou aucune confiance {#5-une-adresse-fiable-ou-aucune-confiance}&quot;">​</a></h3><p>Le Core ne lit <strong>aucun</strong> en-tête <code>X-Forwarded-For</code> lui-même. C&#39;est uvicorn qui corrige l&#39;adresse du client (<code>--proxy-headers</code>), et seulement pour les pairs listés dans <code>FORWARDED_ALLOW_IPS</code>. Tous les autres sont pris à leur adresse réelle. Une seule fonction du Core (<code>client_ip</code>) lit cette adresse, pour la limite comme pour le captcha.</p><p>Le BFF de l&#39;admin transmet l&#39;adresse du navigateur. Sans cela, l&#39;API compterait tout le back-office comme un seul client. Il transmet l&#39;adresse de son pair TCP, jamais un en-tête reçu, sauf si le déploiement l&#39;a explicitement placé derrière un proxy (<code>NUXT_TRUST_FORWARDED_FOR</code>).</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Mémoire du processus</strong></td><td>Fausse dès deux workers ou deux instances : chaque processus compte de son côté, et un redémarrage remet tout à zéro.</td></tr><tr><td><strong>Redis</strong></td><td>Le standard, et plus rapide. Mais il remettait dans la pile un service qu&#39;on venait d&#39;en retirer, et une instance sans Redis n&#39;aurait plus été protégée. PostgreSQL est déjà là, et l&#39;écriture ne touche que des routes anonymes.</td></tr><tr><td><strong>Proxy inverse seul</strong> (nginx, Traefik)</td><td>Rien d&#39;opposable : une installation sans proxy configuré reste ouverte, et le proxy ne connaît pas la cible, qui est dans le corps de la requête.</td></tr><tr><td><strong>Fenêtre glissante</strong></td><td>Une ligne par requête, ou une lecture de plus par requête, pour une précision dont ces seuils n&#39;ont pas besoin.</td></tr><tr><td><strong>Seuils par organisation</strong></td><td>Une organisation pourrait lever la protection d&#39;une instance partagée.</td></tr><tr><td><strong>Lire <code>X-Forwarded-For</code> dans l&#39;application</strong></td><td>Un parseur qui croirait l&#39;en-tête de n&#39;importe qui laisserait chaque client choisir son adresse, donc son compteur.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Les dix familles de routes anonymes ont une limite dès l&#39;installation : connexion, inscription, installation, assistant public (ouverture et tours), dépôts publics, abonnements, suivi par jeton, recherche, défis anti-robot.</li><li>Le coût de l&#39;assistant public est borné par visiteur, pas seulement par le plafond global.</li><li>L&#39;adresse transmise au fournisseur de captcha devient la vraie.</li></ul><p><strong>Négatives, et il y en a</strong></p><ul><li><strong>Une écriture en base par requête limitée</strong>, refusée ou non. C&#39;est le prix de la justesse sur plusieurs instances.</li><li><strong>Un tiers peut épuiser le compteur d&#39;une cible</strong> : quinze minutes de connexion refusées sur un login, un jour d&#39;inscription refusé pour une adresse. C&#39;est le même compromis que le verrouillage de compte.</li><li><strong>Derrière une même sortie réseau</strong> (guichet de mairie, établissement scolaire), tout le monde partage le compteur par adresse. Les seuils par défaut en tiennent compte, sans pouvoir le faire pour tous les cas : l&#39;exploitant les ajuste.</li><li><strong>La limite par adresse ne vaut que ce que vaut <code>FORWARDED_ALLOW_IPS</code>.</strong> Une API joignable sans passer par le proxy, ou une liste trop large, laisse chacun choisir son adresse. La notice le dit. En développement, <code>docker-compose.yml</code> déclare les plages réseau de Docker, ce qui inclut le poste lui-même.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Rendre l&#39;énumération des logins usagers insensible au temps de réponse : aucun hachage n&#39;est fait pour un login inconnu. → <strong>Close</strong> le 18/09/2026 (commit <code>028291e</code>) : tout refus de connexion, agent ou usager, et l&#39;inscription coûtent une dérivation scrypt.</li><li>[x] Décider d&#39;un captcha à l&#39;inscription usager. → <strong>Close</strong> le 18/09/2026 (commit <code>028291e</code>) : captcha exigé, inscription refusée sans captcha configuré — même règle que l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0015-captcha-non-configure-refus-de-soumission">ADR-0015</a>.</li></ul>',34)])])}const g=t(r,[["render",a]]);export{m as __pageData,g as default};
